def decide(trace):
    """
    Decide whether cmd_ack is constrained for the scenario:
      cmd=4, din=1, ena=1, nReset=1, rst=0, scl_i=1, sda_i=0

    Returns (ok, edge, why)
      ok: True  -> check passed (cmd_ack matches requirement)
          False -> check failed (cmd_ack violates requirement)
          None  -> scenario never occurred in the trace
      edge: Always False here (no edge semantics used for this check)
      why: Short human-readable justification.
    """
    target = {
        'cmd': 4,
        'din': 1,
        'ena': 1,
        'nReset': 1,
        'rst': 0,
        'scl_i': 1,
        'sda_i': 0
    }

    matching_rows = []
    for row in trace:
        inputs = row.get('inputs', {})
        match = True
        for k, v in target.items():
            if k not in inputs:
                match = False
                break
            # allow truthy/0/1 and ints
            try:
                if int(inputs[k]) != int(v):
                    match = False
                    break
            except Exception:
                match = False
                break
        if match:
            matching_rows.append(row)

    if not matching_rows:
        return (None, False, "Scenario (cmd=4, din=1, ena=1, nReset=1, rst=0, scl_i=1, sda_i=0) did not occur in the trace.")

    # Requirement: only START, STOP, READ, WRITE cause a cmd_ack pulse at end of their sequences.
    # Any unsupported command leaves the FSM in idle. Thus for an unsupported cmd value (here 4),
    # the FSM should remain idle and must not generate a cmd_ack pulse. Therefore cmd_ack == 0.
    for row in matching_rows:
        outputs = row.get('outputs', {})
        # If cmd_ack is absent, treat it as 0 (not asserted).
        cmd_ack = int(outputs.get('cmd_ack', 0))
        if cmd_ack != 0:
            return (False, False,
                    "Found cmd_ack != 0 for unsupported command (cmd=4). Spec requires unsupported commands leave FSM idle and not assert cmd_ack.")
    return (True, False, "cmd_ack == 0 for all occurrences of the unsupported command (cmd=4), as required: unsupported commands leave FSM idle and do not assert cmd_ack.")
